-- Synthetic identities only, rolled back in full. No existing finances touched.
begin;
do $test$
declare u uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); s uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); i uuid:=gen_random_uuid(); e uuid:=gen_random_uuid(); cc uuid:=gen_random_uuid(); inv uuid:=gen_random_uuid(); e2 uuid:=gen_random_uuid(); cash_before numeric; events_before integer; rejected boolean;
begin
 insert into auth.users(id,email) values(u,'recognition-'||u::text||'@example.invalid'),(outsider,'outsider-'||outsider::text||'@example.invalid');
 insert into public.financial_spaces(id,owner_id,name) values(s,u,'Synthetic recognition test');
 insert into public.space_members(space_id,user_id,role) values(s,u,'owner') on conflict do nothing;
 insert into public.accounts(id,space_id,name,type) values(a,s,'Synthetic account','checking');
 insert into public.debts(id,space_id,name,creditor,original_amount,opening_balance,total_installments) values(d,s,'Synthetic debt','Synthetic',100,100,1);
 insert into public.debt_installments(id,space_id,debt_id,installment_number,due_date,planned_amount) values(i,s,d,1,current_date,100);
 insert into public.financial_events(id,space_id,event_type,description,amount,currency,occurred_at,competence_date,status,source) values(e,s,'expense','Synthetic PIX',100,'BRL',now(),current_date,'confirmed','app');
 insert into public.financial_impacts(event_id,space_id,dimension,amount,account_id,effective_date) values(e,s,'cash',-100,a,current_date),(e,s,'economic',100,null,current_date),(e,s,'budget',100,null,current_date);
 select sum(amount) into cash_before from public.financial_impacts where space_id=s and dimension='cash';
 select count(*) into events_before from public.financial_events where space_id=s;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 rejected:=false; begin perform public.recognize_existing_payment(s,e,'debt',i); exception when insufficient_privilege then rejected:=true; end;
 if not rejected then raise exception 'cross_space_write_allowed'; end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.recognize_existing_payment(s,e,'debt',i);
 perform public.recognize_existing_payment(s,e,'debt',i);
 if (select count(*) from public.debt_payments where event_id=e)<>1 then raise exception 'duplicate_debt_backing'; end if;
 if (select status from public.debt_installments where id=i)<>'paid' then raise exception 'debt_not_paid'; end if;
 if (select count(*) from public.financial_events where space_id=s)<>events_before then raise exception 'extra_cash_event_created'; end if;
 if (select sum(amount) from public.financial_impacts where space_id=s and dimension='cash')<>cash_before then raise exception 'cash_changed'; end if;
 if exists(select 1 from public.financial_impacts where event_id=e and dimension in ('budget','economic')) then raise exception 'double_expense'; end if;
 rejected:=false; begin update public.financial_events set status='cancelled' where id=e; exception when others then rejected:=sqlerrm='unlink_recognized_payment_first'; end;
 if not rejected then raise exception 'linked_event_cancelled'; end if;
 perform public.unlink_recognized_payment(s,e);
 perform public.unlink_recognized_payment(s,e);
 if (select event_type from public.financial_events where id=e)<>'expense' or (select paid_amount from public.debt_installments where id=i)<>0 then raise exception 'unlink_not_restored'; end if;
 if (select count(*) from public.financial_impacts where event_id=e)<>3 then raise exception 'original_impacts_not_restored'; end if;
 insert into public.credit_cards(id,space_id,name,closing_day,due_day) values(cc,s,'Synthetic card',10,20);
 insert into public.card_invoices(id,space_id,card_id,reference_month,closing_date,due_date,opening_balance,status) values(inv,s,cc,date_trunc('month',current_date)::date,current_date,current_date,150,'open');
 perform public.recognize_existing_payment(s,e,'invoice',inv);
 if (select status from public.card_invoices where id=inv)<>'partially_paid' then raise exception 'partial_invoice_not_recognized'; end if;
 rejected:=false; begin perform public.recognize_existing_payment(s,e,'debt',i); exception when others then rejected:=sqlerrm='invalid_payment_candidate'; end;
 if not rejected then raise exception 'same_event_linked_twice'; end if;
 insert into public.financial_events(id,space_id,event_type,description,amount,currency,occurred_at,competence_date,status,source) values(e2,s,'expense','Synthetic excess',100,'BRL',now(),current_date,'confirmed','app');
 insert into public.financial_impacts(event_id,space_id,dimension,amount,account_id,effective_date) values(e2,s,'cash',-100,a,current_date);
 rejected:=false; begin perform public.recognize_existing_payment(s,e2,'invoice',inv); exception when others then rejected:=sqlerrm='payment_exceeds_outstanding_balance'; end;
 if not rejected then raise exception 'overpayment_allowed'; end if;
 perform public.unlink_recognized_payment(s,e);
 if (select status from public.card_invoices where id=inv)='paid' or exists(select 1 from public.card_payments where event_id=e) then raise exception 'invoice_unlink_failed'; end if;
 if (select sum(amount) from public.financial_impacts where event_id=e and dimension='cash')<>-100 then raise exception 'cash_changed_after_unlink'; end if;
end; $test$;
rollback;
